 "content": "def transform(grid):
    """Draw a five-cell-wide marker motif around every 3."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]

    for r, c in markers:
        # Roof and top stem.
        for x in range(c - 2, c + 3):
            if 0 <= r - 2 < h and 0 <= x < w:
                out[r - 2][x] = 5
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        # Side rails, leaving the marker and center column open.
        for y in (r - 1, r, r + 1):
            for x in (c - 2, c + 2):
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = 2
        # A full-width band two rows below the marker, with a five-cell 8 segment.
        y = r + 2
        if 0 <= y < h:
            for x in range(w):
                out[y][x] = 2
            for x in range(c - 2, c + 3):
                if 0 <= x < w:
                    out[y][x] = 8
    return out
